public static AAXSalesPackingSlipPostedBusinessEventContract newFromCustPackingSlipJour(CustPackingSlipJour _custPackingSlipJour)
{
    var contract = new AAXSalesPackingSlipPostedBusinessEventContract();
    contract.initialize(_custPackingSlipJour);

    return contract;
}

