    salesOrderId = _custPackingSlipJour.SalesId;
    customerAccount = _custPackingSlipJour.OrderAccount;
    packingSlipId = _custPackingSlipJour.PackingSlipId;
    deliveryDate = _custPackingSlipJour.DeliveryDate;
}

